def eui64(mac):
    b = [int(x, 16) for x in mac.split(":")]
    b[0] ^= 0x02
    groups = [b[0] << 8 | b[1], b[2] << 8 | 0xFF, 0xFE << 8 | b[3], b[4] << 8 | b[5]]
    return "fe80::" + ":".join(f"{g:x}" for g in groups)

print(eui64("f0:18:98:3a:6d:21"))

