#!/usr/bin/env python3
"""ipcalc.py - a small IPv4 subnet calculator.

Usage:  ./ipcalc.py 192.168.1.23/26
        ./ipcalc.py 192.168.1.23/255.255.255.192
        ./ipcalc.py 192.168.1.23/0xffffffc0 --lib
"""
import argparse
import ipaddress
import sys

FULL = 0xFFFFFFFF


def to_int(dotted):
    parts = dotted.split(".")
    if len(parts) != 4 or not all(p.isdigit() and 0 <= int(p) <= 255 for p in parts):
        raise ValueError(f"not an IPv4 address: {dotted!r}")
    a, b, c, d = (int(p) for p in parts)
    return a << 24 | b << 16 | c << 8 | d


def to_dotted(n):
    return ".".join(str((n >> shift) & 255) for shift in (24, 16, 8, 0))


def mask_from_prefix(prefix):
    if not 0 <= prefix <= 32:
        raise ValueError(f"prefix must be 0..32, got {prefix}")
    return (FULL << (32 - prefix)) & FULL


def prefix_from_mask(mask):
    ones = bin(mask).count("1")
    if mask_from_prefix(ones) != mask:
        raise ValueError(f"{to_dotted(mask)} is not a valid netmask (ones must be contiguous)")
    return ones


def parse_mask(text):
    """Accept 26, /26, 255.255.255.192 or 0xffffffc0 and return a prefix length."""
    text = text.lstrip("/")
    if text.lower().startswith("0x"):
        return prefix_from_mask(int(text, 16))
    if "." in text:
        return prefix_from_mask(to_int(text))
    return int(text)


def calc_math(address, prefix):
    ip = to_int(address)
    mask = mask_from_prefix(prefix)
    wildcard = ~mask & FULL
    network = ip & mask
    broadcast = network | wildcard
    total = 2 ** (32 - prefix)
    if prefix >= 31:                      # /31 and /32 have no network/broadcast overhead
        first, last, usable = network, broadcast, total
    else:
        first, last, usable = network + 1, broadcast - 1, total - 2
    return {
        "address": address,
        "prefix": prefix,
        "netmask": to_dotted(mask),
        "netmask_hex": f"0x{mask:08x}",
        "wildcard": to_dotted(wildcard),
        "network": to_dotted(network),
        "broadcast": to_dotted(broadcast),
        "first": to_dotted(first),
        "last": to_dotted(last),
        "usable": usable,
    }

def show(info):
    for key in ("address", "netmask", "netmask_hex", "wildcard", "network", "broadcast", "first", "last", "usable"):
        print(f"{key:<12}{info[key]}")
    print(f"{'cidr':<12}{info['network']}/{info['prefix']}")


def main(argv=None):
    parser = argparse.ArgumentParser(description="IPv4 subnet calculator")
    parser.add_argument("target", help="address/prefix, address/dotted-mask or address/0xhexmask")
    parser.add_argument("--lib", action="store_true", help="use the ipaddress module instead of pure maths")
    args = parser.parse_args(argv)
    try:
        address, _, mask_text = args.target.partition("/")
        prefix = parse_mask(mask_text or "32")
        info = (calc_lib if args.lib else calc_math)(address, prefix)
    except ValueError as e:
        print(f"ipcalc: {e}", file=sys.stderr)
        return 2
    show(info)
    return 0


if __name__ == "__main__":
    sys.exit(main())
